
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_21_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_21", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.240334648955473e+00, -5.137792627049539e+00, -4.993907946245155e+00, -4.794130304729659e+00, -4.520787964105693e+00, -4.154126820797686e+00, -3.674461079309239e+00, -3.064118648792921e+00, -2.310564851862840e+00, -1.471355206717297e+00, -8.345931307438339e-01, -6.176337729477949e-01, -6.345061667214825e-01, -5.474191688859926e-01, -3.624116153279826e-01, -1.859142172756636e-01, -7.738326854095033e-02, -2.521357234985080e-02, -5.394556989126988e-03, -6.064657500000146e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


